excels.excel:

EXPORT WITH SHEET="来料检验不合格记录表", HEADER=true,
    MAPPING={"a":"批次号","b":"物料名称","c":"供应商","d":"送检数量","e":"不合格数量","f":"不合格率","g":"处理方式"},
    FORMAT={"d":"#,##0","e":"#,##0","f":"0.00%"},
    FORMULAS={
        F2:'E2/D2',F3:'E3/D3',F4:'E4/D4',F5:'E5/D5',F6:'E6/D6',F7:'E7/D7',
        D8:'SUM(D2:D7)',E8:'SUM(E2:E7)',F8:'E8/D8'
    },
    STYLE={
        ROW 8:{bold:true,fillPattern:solid_foreground,fillForegroundColor:lightYellow,alignment:right,verticalAlignment:center},
        F4:{color:red,bold:true}
    }
